/**
 * @name Unsafe Path Traversal
 * @description Path traversal in packaging backend
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-packaging
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Sources: Environment variables via os.environ.get()
    source = API::moduleImport("os").getMember("environ").getMember("get").getACall()
    or
    // Sources: Direct access to os.environ (e.g. os.environ['VAR'])
    source = API::moduleImport("os").getMember("environ").getAValueReachableFromSource()
    or
    // Sources: Command line arguments (sys.argv)
    source = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource()
    or
    // Sources: os.path.expandvars() results
    source = API::moduleImport("os").getMember("path").getMember("expandvars").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "external input"

/**
 * @name Subprocess command injection
 * @description Using subprocess or os.system with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/subprocess-command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module SubprocessCommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Sources: Environment variables via os.environ.get()
    source = API::moduleImport("os").getMember("environ").getMember("get").getACall()
    or
    // Sources: Direct access to os.environ (e.g. os.environ['VAR'])
    source = API::moduleImport("os").getMember("environ").getAValueReachableFromSource()
    or
    // Sources: Command line arguments (sys.argv)
    source = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource()
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(SystemCommandExecution sce).getCommand()
  }
}

module SubprocessCommandInjectionFlow = TaintTracking::Global<SubprocessCommandInjectionConfig>;
import SubprocessCommandInjectionFlow::PathGraph

from SubprocessCommandInjectionFlow::PathNode source, SubprocessCommandInjectionFlow::PathNode sink
where SubprocessCommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "external input"

/**
 * @name Uncontrolled attribute modification
 * @description Modifying object attributes with user-controlled names can lead to unexpected behavior
 * @kind path-problem
 * @problem.severity warning
 * @id py/attribute-modification
 * @tags security
 *       external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module AttributeModificationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
     // Sources: Environment variables via os.environ.get()
    source = API::moduleImport("os").getMember("environ").getMember("get").getACall()
    or
    // Sources: Direct access to os.environ (e.g. os.environ['VAR'])
    source = API::moduleImport("os").getMember("environ").getAValueReachableFromSource()
    or
    // Sources: Command line arguments (sys.argv)
    source = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource()
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1) // The attribute name argument
    )
  }
}

module AttributeModificationFlow = TaintTracking::Global<AttributeModificationConfig>;
import AttributeModificationFlow::PathGraph

from AttributeModificationFlow::PathNode source, AttributeModificationFlow::PathNode sink
where AttributeModificationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Attribute modification with user-controlled name from $@.", source.getNode(), "external input"
